const stepsHTML=()=>`<div class="steps"><div class="step-i"><div class="shield">1</div><div><h3>Tell us about your vehicle</h3><p>Year, make, model and mileage. No VIN hunting.</p></div></div><div class="step-i"><div class="shield">2</div><div><h3>Choose what to protect</h3><p>A service contract, everyday protection, or both. Unsure? We'll recommend.</p></div></div><div class="step-i"><div class="shield">3</div><div><h3>Get a call with your quote</h3><p>A specialist calls at the time you choose with a personalized quote. No obligation.</p></div></div></div>`;
